#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/semantics/types/semantic_types.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// DrawingSurface's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/drawing_surface.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// Whether pointer input hits the surface (default false: it passes through to what lies beneath).
template <typename Declaring>
struct DrawingSurfaceHitTestVisibleCapability {
    PropertyCell<bool, DrawingSurfaceHitTestVisibleCapability<Declaring>> hit_test_visible{};

    static void assign(DrawingSurfaceHitTestVisibleCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.hit_test_visible), incoming);
        if (!capability.hit_test_visible.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.hit_test_visible));
    }
};

// The role the surface publishes to accessibility (default image).
template <typename Declaring>
struct DrawingSurfaceSemanticRoleCapability {
    PropertyCell<SemanticRole, DrawingSurfaceSemanticRoleCapability<Declaring>> semantic_role{SemanticRole::image};

    static void assign(DrawingSurfaceSemanticRoleCapability& capability, SemanticRole incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.semantic_role), incoming);
        if (!capability.semantic_role.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.semantic_role));
    }
};

// The fill painted over the bounds before the paint callback (default transparent).
template <typename Declaring>
struct DrawingSurfaceBackgroundCapability {
    PropertyCell<Color, DrawingSurfaceBackgroundCapability<Declaring>> background{Color::rgba(0, 0, 0, 0)};

    static void assign(DrawingSurfaceBackgroundCapability& capability, Color incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.background), incoming);
        if (!capability.background.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.background));
    }
};

// Every DrawingSurface capability, in the order the declaring class takes them.
template <typename Declaring>
struct DrawingSurfaceCapabilities : public DrawingSurfaceHitTestVisibleCapability<Declaring>,
                                    public DrawingSurfaceSemanticRoleCapability<Declaring>,
                                    public DrawingSurfaceBackgroundCapability<Declaring> {};

} // namespace gui_forms
